"use client";

import { useActionState, useEffect, useRef } from "react";
import { addComment, type CommentFormState } from "./actions";

export function CommentForm({ postId }: { postId: number }) {
  const [state, action, pending] = useActionState<CommentFormState, FormData>(addComment, {
    error: null,
  });
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!pending && state.error === null) {
      formRef.current?.reset();
    }
  }, [pending, state]);

  return (
    <form ref={formRef} action={action} style={{ display: "grid", gap: 8, marginTop: 8 }}>
      <input type="hidden" name="post_id" value={postId} />
      <textarea
        name="body"
        rows={2}
        maxLength={2000}
        required
        placeholder="Add a comment"
        aria-label="Add a comment"
      />
      <div>
        <button type="submit" disabled={pending}>
          {pending ? "Posting…" : "Comment"}
        </button>
      </div>
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}

